parameters.jsCode:
const entrada = $input.first().json ?? {};
const body = entrada.body ?? {};
const headers = entrada.headers ?? {};

const texto = (valor) =>
  typeof valor === "string" ? valor.trim() : "";

const tieneCampo = (nombre) =>
  Object.prototype.hasOwnProperty.call(body, nombre);

const obtenerHeader = (nombre) => {
  const buscado = nombre.toLowerCase();

  for (const [clave, valor] of Object.entries(headers)) {
    if (clave.toLowerCase() === buscado) {
      return texto(valor);
    }
  }

  return "";
};

const internalSessionId = texto(body.internal_session_id);
const message = texto(body.message);
const accion = texto(body.accion).toLowerCase();
const recursoId = texto(body.recurso_id);
const appointmentId = texto(body.appointment_id);
const resultadoAtencion = texto(body.resultado_atencion).toLowerCase();
const fechaObjetivo = texto(body.fecha_objetivo);
const tipoSeguimiento = texto(body.tipo_seguimiento).toLowerCase();

const estadoObjetivo = texto(body.estado_objetivo).toLowerCase();

const tipo = texto(body.tipo).toLowerCase();
const titulo = texto(body.titulo);
const descripcion = texto(body.descripcion);
const prioridad = texto(body.prioridad).toLowerCase();
const asignadoA = texto(body.asignado_a);
const fechaLimite = texto(body.fecha_limite);

const origenTipo = texto(body.origen_tipo).toLowerCase();
const origenId = texto(body.origen_id);
const motivo = texto(body.motivo);
const rolDestino = texto(body.rol_destino).toLowerCase();
const usuarioDestino = texto(body.usuario_destino);

const identityProvider = obtenerHeader(
  "x-vetatiende-identity-provider"
);

const identitySubject = obtenerHeader(
  "x-vetatiende-identity-subject"
);

return [
  {
    json: {
      internal_session_id: internalSessionId,
      message,
      accion,
      recurso_id: recursoId,
      appointment_id: appointmentId,
      resultado_atencion: resultadoAtencion,
      fecha_objetivo: fechaObjetivo,
      tipo_seguimiento: tipoSeguimiento,

      estado_objetivo: estadoObjetivo,

      tipo,
      titulo,
      descripcion,
      prioridad,
      asignado_a: asignadoA,
      fecha_limite: fechaLimite,

      titulo_presente: tieneCampo("titulo"),
      descripcion_presente: tieneCampo("descripcion"),
      prioridad_presente: tieneCampo("prioridad"),
      asignado_a_presente: tieneCampo("asignado_a"),
      fecha_limite_presente: tieneCampo("fecha_limite"),
      estado_objetivo_presente: tieneCampo("estado_objetivo"),

      origen_tipo: origenTipo,
      origen_id: origenId,
      motivo,
      rol_destino: rolDestino,
      usuario_destino: usuarioDestino,

      identity_provider: identityProvider,
      identity_subject: identitySubject,

      solicitud_valida:
        internalSessionId.length > 0 &&
        accion.length > 0,

      identidad_presente:
        identityProvider.length > 0 &&
        identitySubject.length > 0,

      error_solicitud:
        internalSessionId.length === 0
          ? "internal_session_id_requerido"
          : accion.length === 0
            ? "accion_requerida"
            : "",

      recibido_en: new Date().toISOString()
    }
  }
];

