const contexto =
  $("Normalizar solicitud interna LAB-025").first().json ?? {};

const providerEsperado =
  typeof contexto.identity_provider === "string"
    ? contexto.identity_provider.trim()
    : "";

const subjectEsperado =
  typeof contexto.identity_subject === "string"
    ? contexto.identity_subject.trim()
    : "";

const filas = $input
  .all()
  .map(item => item.json ?? {})
  .filter(row => {
    const userId =
      typeof row.user_id === "string"
        ? row.user_id.trim()
        : "";

    const provider =
      typeof row.identity_provider === "string"
        ? row.identity_provider.trim()
        : "";

    const subject =
      typeof row.identity_subject === "string"
        ? row.identity_subject.trim()
        : "";

    return (
      userId.length > 0 &&
      provider === providerEsperado &&
      subject === subjectEsperado
    );
  });

const cantidad = filas.length;

if (cantidad === 0) {
  return [
    {
      json: {
        ...contexto,

        usuario_encontrado: false,
        usuario_duplicado: false,

        user_id: "",
        clinic_id: "",
        nombre: "",
        rol: "",
        estado_usuario: "",

        error_identidad: "usuario_interno_no_encontrado"
      }
    }
  ];
}

if (cantidad > 1) {
  return [
    {
      json: {
        ...contexto,

        usuario_encontrado: false,
        usuario_duplicado: true,

        user_id: "",
        clinic_id: "",
        nombre: "",
        rol: "",
        estado_usuario: "",

        error_identidad: "identidad_interna_duplicada"
      }
    }
  ];
}

const usuario = filas[0];

return [
  {
    json: {
      ...contexto,

      usuario_encontrado: true,
      usuario_duplicado: false,

      user_id:
        typeof usuario.user_id === "string"
          ? usuario.user_id.trim()
          : "",

      clinic_id:
        typeof usuario.clinic_id === "string"
          ? usuario.clinic_id.trim()
          : "",

      nombre:
        typeof usuario.nombre === "string"
          ? usuario.nombre.trim()
          : "",

      rol:
        typeof usuario.rol === "string"
          ? usuario.rol.trim().toLowerCase()
          : "",

      estado_usuario:
        typeof usuario.estado === "string"
          ? usuario.estado.trim().toLowerCase()
          : "",

      error_identidad: ""
    }
  }
];

