const contexto =
  $("Consolidar búsqueda usuario interno").first().json ?? {};

const clinicIdEsperado =
  typeof contexto.clinic_id === "string"
    ? contexto.clinic_id.trim()
    : "";

const rolEsperado =
  typeof contexto.rol === "string"
    ? contexto.rol.trim().toLowerCase()
    : "";

const filasValidas = $input
  .all()
  .map(item => item.json ?? {})
  .filter(row => {
    const clinicId =
      typeof row.clinic_id === "string"
        ? row.clinic_id.trim()
        : "";

    const rol =
      typeof row.rol === "string"
        ? row.rol.trim().toLowerCase()
        : "";

    const estado =
      typeof row.estado === "string"
        ? row.estado.trim().toLowerCase()
        : "";

    return (
      clinicId === clinicIdEsperado &&
      rol === rolEsperado &&
      estado === "activo"
    );
  });

const permisos = [
  ...new Set(
    filasValidas
      .map(row => row.permiso)
      .filter(valor =>
        typeof valor === "string" &&
        valor.trim().length > 0
      )
      .map(valor => valor.trim().toLowerCase())
  )
];

return [
  {
    json: {
      ...contexto,

      permisos,
      cantidad_permisos: permisos.length,
      permisos_encontrados: permisos.length > 0,

      error_permisos:
        permisos.length > 0
          ? ""
          : "rol_sin_permisos_activos"
    }
  }
];

