const item = $input.item;

const binarios = item.binary ?? {};
const claveBinaria = Object.keys(binarios)[0];

if (!claveBinaria) {
  throw new Error("documento_rag_interno_sin_binario");
}

const archivo = binarios[claveBinaria] ?? {};
const nombreArchivo =
  typeof archivo.fileName === "string"
    ? archivo.fileName.trim()
    : "";

const documentos = {
  "manual_procedimientos_internos.pdf": {
    document_id: "doc_interno_procedimientos_001",
    tipo_documento: "procedimientos_internos",
    nivel_acceso: "recepcion"
  },

  "manual_seguridad_y_derivacion.pdf": {
    document_id: "doc_interno_seguridad_001",
    tipo_documento: "seguridad_y_derivacion",
    nivel_acceso: "veterinario"
  },

  "protocolo_stock.csv": {
    document_id: "doc_interno_stock_001",
    tipo_documento: "stock_operativo",
    nivel_acceso: "recepcion"
  }
};

const config = documentos[nombreArchivo];

if (!config) {
  throw new Error("documento_rag_interno_no_configurado");
}

return {
  json: {
    ...item.json,

    clinic_id: "clinica_piloto_001",
    document_id: config.document_id,
    tipo_documento: config.tipo_documento,
    nivel_acceso: config.nivel_acceso,

