};

const entrada = $input.first().json ?? {};

const rol =
  typeof entrada.rol === "string"
    ? entrada.rol.trim().toLowerCase()
    : "";

const consulta =
  typeof entrada.message === "string"
    ? entrada.message.trim()
    : "";

const nivelesPorRol = {
