    "veterinario",
    "administrador"
  ]
};

const nivelesAcceso =
  nivelesPorRol[rol] ?? [];

return [
  {
    json: {
      ...entrada,

      consulta_rag: consulta,
      niveles_acceso_permitidos: nivelesAcceso,

