const solicitud =
  $("Preparar consulta RAG interno autorizada").first().json ?? {};

const resultados = $input.all();

const UMBRAL_SCORE = 0.50;

const fragmentosRecuperados = resultados
  .map((item) => {
    const documento =
      item.json?.document ?? {};

    const metadata =
      documento.metadata ?? {};

    const contenido =
      typeof documento.pageContent === "string"
        ? documento.pageContent.trim()
        : "";

    const score =
      typeof item.json?.score === "number"
        ? item.json.score
        : null;

    const documentId =
      typeof metadata.document_id === "string"
        ? metadata.document_id.trim()
        : "";

    const tipoDocumento =
      typeof metadata.tipo_documento === "string"
        ? metadata.tipo_documento.trim()
        : "";

    const nivelAcceso =
      typeof metadata.nivel_acceso === "string"
        ? metadata.nivel_acceso.trim()
        : "";

    if (!contenido) {
      return null;
    }

    return {
      contenido,
      score,
      document_id: documentId,
      tipo_documento: tipoDocumento,
      nivel_acceso: nivelAcceso
    };
  })
  .filter(Boolean);

const fragmentosConfiables =
  fragmentosRecuperados.filter((fragmento) => {
    return (
      typeof fragmento.score === "number" &&
      Number.isFinite(fragmento.score) &&
      fragmento.score >= UMBRAL_SCORE &&
      fragmento.document_id.length > 0
    );
  });

const contextoRag =
  fragmentosConfiables
    .map(
      (fragmento, indice) =>
        `[Fragmento ${indice + 1}]
Documento: ${fragmento.document_id}
Tipo: ${fragmento.tipo_documento}
Contenido:
${fragmento.contenido}`
    )
    .join("\n\n");

const fuentes = [
  ...new Set(
    fragmentosConfiables
      .map((fragmento) => fragmento.document_id)
      .filter((documentId) => documentId.length > 0)
  )
];

return [
  {
    json: {
      ...solicitud,

      rag_resultados: fragmentosConfiables.length,

      rag_contexto_disponible:
        fragmentosConfiables.length > 0,

      rag_fuentes: fuentes,

      contexto_rag_interno: contextoRag
    }
  }
];

