parameters.jsCode:
const solicitud =
  $("Consolidar contexto RAG interno").first().json ?? {};

const salida = $input.first().json ?? {};

const respuesta =
  typeof salida.text === "string"
    ? salida.text.trim()
    : typeof salida.output === "string"
      ? salida.output.trim()
      : "";

const fuentes = Array.isArray(solicitud.rag_fuentes)
  ? solicitud.rag_fuentes
  : [];

const respuestaIndicaInsuficiencia =
  /no (?:contiene|encuentro|hay|dispongo)|informaci[oó]n (?:interna )?(?:disponible )?(?:no es suficiente|insuficiente)|requiere revisi[oó]n|consulte al responsable/i
    .test(respuesta);

const requiereRevisionHumana =
  respuesta.length === 0 ||
  fuentes.length === 0 ||
  respuestaIndicaInsuficiencia;

return [
  {
    json: {
      ok: true,
      action: solicitud.accion || "consulta_rag_interno",
      message:
        respuesta.length > 0
          ? respuesta
          : "No fue posible generar una respuesta interna segura.",
      data: {
        fuentes,
        requiere_revision_humana: requiereRevisionHumana
      }
    }
  }
];

