const estadoActual = String(
  $json.estado_pendiente_actual || ''
).trim().toLowerCase();

const estadoObjetivo = String(
  $json.estado_objetivo || ''
).trim().toLowerCase();

const prioridadActual = String(
  $json.prioridad_anterior ??
  $json.pendiente_actual?.prioridad ??
  ''
).trim().toLowerCase();

const prioridadNueva = String(
  $json.prioridad_nueva ??
  $json.prioridad ??
  ''
).trim().toLowerCase();

const asignadoActual = String(
  $json.asignado_anterior ??
  $json.pendiente_actual?.asignado_a ??
  ''
).trim();

const asignadoNuevo = String(
  $json.asignado_nuevo ??
  $json.asignado_a ??
  ''
).trim();

const actualizarEstado = Boolean($json.actualizar_estado);
const actualizarPrioridad = Boolean($json.actualizar_prioridad);
const actualizarAsignado = Boolean($json.actualizar_asignado);

const cambioPrioridadReal =
  actualizarPrioridad &&
  prioridadNueva !== prioridadActual;

const cambioAsignadoReal =
  actualizarAsignado &&
  asignadoNuevo !== asignadoActual;

let transicionValida = true;
let cambioEstadoReal = false;

if (actualizarEstado) {
  cambioEstadoReal =
    estadoObjetivo !== estadoActual;

  transicionValida =
    (estadoActual === 'pendiente' &&
      estadoObjetivo === 'en_proceso') ||
    (estadoActual === 'en_proceso' &&
      estadoObjetivo === 'resuelto');
}

/*
 * Una solicitud de estado siempre se trata como una transición.
 * Por eso:
 * resuelto → resuelto
 * pendiente → pendiente
 * etc.
 * siguen siendo transiciones inválidas (HTTP 409).
 *
 * "Sin cambios" se aplica cuando NO se solicita cambio de estado
 * y prioridad/asignación mantienen exactamente sus valores actuales.
 */
const actualizacionSinCambios =
  !actualizarEstado &&
  !cambioPrioridadReal &&
  !cambioAsignadoReal;

const puedeContinuar =
  transicionValida &&
  !actualizacionSinCambios;

return {
  json: {
    ...$json,

    cambio_prioridad_real: cambioPrioridadReal,
    cambio_asignado_real: cambioAsignadoReal,
    cambio_estado_real: cambioEstadoReal,

    actualizacion_pendiente_sin_cambios:
      actualizacionSinCambios,

    transicion_pendiente_valida:
      puedeContinuar,

    requiere_validar_asignado_actualizacion:
      cambioAsignadoReal
  }
};

