const contexto =
  $('Resolver permiso requerido por acción').first().json ?? {};

const clinicId = String(contexto.clinic_id || '').trim();
const userId = String(contexto.user_id || '').trim();
const rol = String(contexto.rol || '').trim().toLowerCase();

const derivaciones = $input
  .all()
  .map(item => item.json ?? {})
  .filter(row => {
    const referralId = String(row.referral_id || '').trim();
    const rowClinicId = String(row.clinic_id || '').trim();
    const rolDestino = String(row.rol_destino || '').trim().toLowerCase();
    const usuarioDestino = String(row.usuario_destino || '').trim();

    if (!referralId || rowClinicId !== clinicId) {
      return false;
    }

    if (rol === 'administrador') {
      return true;
    }

    if (usuarioDestino) {
      return usuarioDestino === userId;
    }

    return rolDestino === rol;
  })
  .map(row => ({
    referral_id: String(row.referral_id || '').trim(),
    origen_tipo: String(row.origen_tipo || '').trim(),
    origen_id: String(row.origen_id || '').trim(),
    motivo: String(row.motivo || '').trim(),
    rol_destino: String(row.rol_destino || '').trim().toLowerCase(),
    usuario_destino: String(row.usuario_destino || '').trim(),
    estado: String(row.estado || '').trim().toLowerCase(),
    creado_por: String(row.creado_por || '').trim(),
    aceptado_por: String(row.aceptado_por || '').trim(),
    resuelto_por: String(row.resuelto_por || '').trim(),
    fecha_creacion: String(row.fecha_creacion || '').trim(),
    fecha_aceptacion: String(row.fecha_aceptacion || '').trim(),
    fecha_resolucion: String(row.fecha_resolucion || '').trim()
  }))
  .sort((a, b) =>
    b.fecha_creacion.localeCompare(a.fecha_creacion)
  );

return [{
  json: {
    ok: true,
    action: 'ver_derivaciones',
    derivaciones,
    cantidad_derivaciones: derivaciones.length
  }
}];

