const fechaLimite = String($json.fecha_limite || '').trim();
const estadoObjetivo = String($json.estado_objetivo || '').trim().toLowerCase();

const prioridadesPermitidas = ['baja', 'media', 'alta'];
const estadosObjetivoPermitidos = ['en_proceso', 'cerrada'];

const actualizarTitulo = Boolean($json.titulo_presente);
const actualizarDescripcion = Boolean($json.descripcion_presente);
const actualizarPrioridad = Boolean($json.prioridad_presente);
const actualizarAsignado = Boolean($json.asignado_a_presente);
const actualizarFechaLimite = Boolean($json.fecha_limite_presente);
const actualizarEstado = Boolean($json.estado_objetivo_presente);

let errorActualizacion = '';

if (!recursoId) {
  errorActualizacion = 'recurso_id_requerido';
} else if (
  !actualizarTitulo &&
  !actualizarDescripcion &&
  !actualizarPrioridad &&
  !actualizarAsignado &&
  !actualizarFechaLimite &&
  !actualizarEstado
) {
  errorActualizacion = 'sin_cambios';
} else if (actualizarTitulo && !titulo) {
  errorActualizacion = 'titulo_invalido';
} else if (actualizarDescripcion && !descripcion) {
  errorActualizacion = 'descripcion_invalida';
} else if (
  actualizarPrioridad &&
  !prioridadesPermitidas.includes(prioridad)
) {
  errorActualizacion = 'prioridad_invalida';
} else if (
  actualizarFechaLimite &&
  fechaLimite &&
  Number.isNaN(Date.parse(fechaLimite))
) {
  errorActualizacion = 'fecha_limite_invalida';
} else if (
  actualizarEstado &&
  !estadosObjetivoPermitidos.includes(estadoObjetivo)
) {
  errorActualizacion = 'estado_objetivo_invalido';
}

return {
  json: {
    ...$json,
    recurso_id: recursoId,
    titulo,
    descripcion,
    prioridad,
    asignado_a: asignadoA,
    fecha_limite: fechaLimite,
    estado_objetivo: estadoObjetivo,

    actualizar_titulo_tarea: actualizarTitulo,
    actualizar_descripcion_tarea: actualizarDescripcion,
    actualizar_prioridad_tarea: actualizarPrioridad,
    actualizar_asignado_tarea: actualizarAsignado,
    actualizar_fecha_limite_tarea: actualizarFechaLimite,
    actualizar_estado_tarea: actualizarEstado,

    solicitud_actualizacion_tarea_valida:
      errorActualizacion === '',

    error_actualizacion_tarea:
      errorActualizacion
  }
};

// LAB027_1G_BEGIN
if ($('Preparar actualización tarea').first().json.accion === 'cerrar_tarea_seguimiento') {
 const solicitud = $('Preparar actualización tarea').first().json;
 const propia = t => {
 if(t.creado_por !== 'sistema_lab027' || typeof t.task_id !== 'string' || !t.task_id.startsWith('task_lab027_')) return false;
 try { const tuple = JSON.parse(decodeURIComponent(t.task_id.slice(12))); return Array.isArray(tuple) && tuple.length === 3 && tuple[0] === solicitud.clinic_id && typeof tuple[1] === 'string' && tuple[1].length > 0 && tuple[2] === 'sin_respuesta_24h' && t.task_id === 'task_lab027_' + encodeURIComponent(JSON.stringify(tuple)); } catch { return false; }
};
 const rows = $input.all().map(i => i.json).filter(t => t.task_id === solicitud.recurso_id && t.clinic_id === solicitud.clinic_id);
 const tarea = rows.length === 1 && propia(rows[0]) ? rows[0] : null;
 return [{json:{...solicitud,tarea_encontrada:Boolean(tarea),estado_tarea_actual:tarea?.estado || null,tarea_actual:tarea}}];
}
// LAB027_1G_END
const solicitud = $('Preparar actualización tarea').first().json;

const taskId = String(solicitud.recurso_id || '').trim();
const clinicId = String(solicitud.clinic_id || '').trim();

const filas = $input.all().map(item => item.json || {});

const tarea = filas.find(fila =>
  String(fila.task_id || '').trim() === taskId &&
  String(fila.clinic_id || '').trim() === clinicId
) || null;

return [{
  json: {
    ...solicitud,
    tarea_encontrada: tarea !== null,
    estado_tarea_actual: tarea
      ? String(tarea.estado || '').trim().toLowerCase()
      : null,
    tarea_actual: tarea
  }
}];

