const descripcionActual = String(tareaActual.descripcion || '').trim();
const prioridadActual = String(tareaActual.prioridad || '').trim().toLowerCase();
const asignadoActual = String(tareaActual.asignado_a || '').trim();
const fechaLimiteActual = String(tareaActual.fecha_limite || '').trim();

const cambioTitulo =
  $json.actualizar_titulo_tarea &&
  $json.titulo !== tituloActual;

const cambioDescripcion =
  $json.actualizar_descripcion_tarea &&
  $json.descripcion !== descripcionActual;

const cambioPrioridad =
  $json.actualizar_prioridad_tarea &&
  $json.prioridad !== prioridadActual;

