  $json.actualizar_asignado_tarea &&
  $json.asignado_a !== asignadoActual;

const cambioFechaLimite =
  $json.actualizar_fecha_limite_tarea &&
  $json.fecha_limite !== fechaLimiteActual;

let transicionValida = true;
let cambioEstado = false;

if ($json.actualizar_estado_tarea) {
  cambioEstado = estadoObjetivo !== estadoActual;

