    (estadoActual === 'pendiente' && estadoObjetivo === 'en_proceso') ||
    (estadoActual === 'en_proceso' && estadoObjetivo === 'cerrada');
}

if (estadoActual === 'cerrada') {
  transicionValida = false;
}

const sinCambios =
  !$json.actualizar_estado_tarea &&
  !cambioTitulo &&
  !cambioDescripcion &&
  !cambioPrioridad &&
  !cambioAsignado &&
  !cambioFechaLimite;

return {
