parameters.jsCode:
const entrada = $input.first()?.json ?? {};

const leerNodoSeguro = (nombre) => {
  try {
    return $(nombre).first()?.json ?? {};
  } catch {
    return {};
  }
};

const normalizada = leerNodoSeguro(
  "Normalizar solicitud interna LAB-025"
);

const usuario = leerNodoSeguro(
  "Consolidar búsqueda usuario interno"
);

const permisos = leerNodoSeguro(
  "Consolidar permisos usuario interno"
);

const autorizacion = leerNodoSeguro(
  "Resolver permiso requerido por acción"
);

const contexto = {
  ...normalizada,
  ...usuario,
  ...permisos,
  ...autorizacion,
  ...entrada
};

const texto = (valor) =>
  valor === null || valor === undefined
    ? ""
    : String(valor).trim();

const primerTexto = (...valores) => {
  for (const valor of valores) {
    const t = texto(valor);
    if (t.length > 0) {
      return t;
    }
  }
  return "";
};

const accion = texto(
  contexto.accion || normalizada.accion
).toLowerCase();

const recursoTipoPorAccion = {
  consulta_rag_interno: "rag_interno",

  ver_alertas: "alerta",
  reconocer_alerta: "alerta",
  actualizar_alerta: "alerta",

  crear_pendiente: "pendiente",
  actualizar_pendiente: "pendiente",

  ver_derivaciones: "derivacion",
  crear_derivacion: "derivacion",
  aceptar_derivacion: "derivacion",
  resolver_derivacion: "derivacion",

  crear_tarea: "tarea",
  actualizar_tarea: "tarea"
};

const recursoTipo =
  recursoTipoPorAccion[accion] ||
  "operacion_interna";

const recursoId = primerTexto(
  contexto.recurso_id,

  contexto.alerta_id_actualizar,
  contexto.alerta_reconocida_persistida?.alert_id,
  contexto.alerta_actualizada_persistida?.alert_id,
  contexto.alerta_cerrada_persistida?.alert_id,

  contexto.pending_id_actualizar,
  contexto.pending_id,
  contexto.pendiente_persistido?.pending_id,
  contexto.pendiente_actualizado_persistido?.pending_id,

  contexto.referral_id_actualizar,
  contexto.referral_id,
  contexto.derivacion_persistida?.referral_id,
  contexto.derivacion_aceptada_persistida?.referral_id,
  contexto.derivacion_resuelta_persistida?.referral_id,

  contexto.task_id_actualizar,
  contexto.task_id,
  contexto.tarea_persistida?.task_id,
  contexto.tarea_actualizada_persistida?.task_id
);

const estadoAnterior = primerTexto(
  contexto.estado_anterior,
  contexto.estado_alerta_actual,
  contexto.estado_pendiente_actual,
  contexto.derivacion_estado_actual,
  contexto.estado_tarea_actual,

  contexto.alerta_actual?.estado_operacion,
  contexto.pendiente_actual?.estado,
  contexto.derivacion_actual_aceptacion?.estado,
  contexto.derivacion_actual_resolucion?.estado,
  contexto.tarea_actual?.estado
).toLowerCase();

let estadoNuevo = primerTexto(
  contexto.estado_nuevo,
  contexto.estado_objetivo,
  contexto.estado_pendiente,
  contexto.estado_derivacion,
  contexto.estado_tarea,

  contexto.alerta_reconocida_persistida?.estado_operacion,
  contexto.alerta_actualizada_persistida?.estado_operacion,
  contexto.alerta_cerrada_persistida?.estado_operacion,

  contexto.pendiente_persistido?.estado,
  contexto.pendiente_actualizado_persistido?.estado,

  contexto.derivacion_persistida?.estado,
  contexto.derivacion_aceptada_persistida?.estado,
  contexto.derivacion_resuelta_persistida?.estado,

  contexto.tarea_persistida?.estado,
  contexto.tarea_actualizada_persistida?.estado
).toLowerCase();

if (!estadoNuevo) {
  if (accion === "reconocer_alerta") {
    estadoNuevo = "reconocida";
  } else if (accion === "crear_pendiente") {
    estadoNuevo = "pendiente";
  } else if (accion === "crear_derivacion") {
    estadoNuevo = "pendiente";
  } else if (accion === "aceptar_derivacion") {
    estadoNuevo = "aceptada";
  } else if (accion === "resolver_derivacion") {
    estadoNuevo = "resuelta";
  } else if (accion === "crear_tarea") {
    estadoNuevo = "pendiente";
  }
}

const permisosActor = Array.isArray(contexto.permisos)
  ? contexto.permisos.map(v => texto(v).toLowerCase())
  : [];

const permisoRequerido = texto(
  contexto.permiso_requerido
).toLowerCase();

let resultado = "exito";
let motivo = "operacion_completada";

const errores = Object.entries(contexto)
  .filter(([clave, valor]) =>
    clave.startsWith("error_") &&
    typeof valor === "string" &&
    valor.trim().length > 0
  )
  .map(([, valor]) => valor.trim());

const valorFalse = (clave) =>
  Object.prototype.hasOwnProperty.call(contexto, clave) &&
  contexto[clave] === false;

const existeFalse = (patron) =>
  Object.entries(contexto).some(
    ([clave, valor]) =>
      valor === false &&
      patron.test(clave)
  );

if (contexto.solicitud_valida === false) {
  resultado = "rechazado";
  motivo =
    texto(contexto.error_solicitud) ||
    "solicitud_interna_invalida";

} else if (contexto.identidad_presente === false) {
  resultado = "denegado";
  motivo = "identidad_interna_faltante";

} else if (contexto.usuario_encontrado === false) {
  resultado = "denegado";
  motivo =
    texto(contexto.error_identidad) ||
    "usuario_interno_no_autorizado";

} else if (
  texto(contexto.estado_usuario) &&
  texto(contexto.estado_usuario).toLowerCase() !== "activo"
) {
  resultado = "denegado";
  motivo = "usuario_interno_inactivo";

} else if (contexto.permisos_encontrados === false) {
  resultado = "denegado";
  motivo =
    texto(contexto.error_permisos) ||
    "rol_sin_permisos_activos";

} else if (contexto.accion_soportada === false) {
  resultado = "rechazado";
  motivo = "accion_interna_no_soportada";

} else if (
  permisoRequerido &&
  permisosActor.length > 0 &&
  !permisosActor.includes(permisoRequerido)
) {
  resultado = "denegado";
  motivo = "permiso_interno_insuficiente";

} else if (
  existeFalse(/^actor_.*_valido$/)
) {
  resultado = "denegado";
  motivo = "actor_no_autorizado_para_recurso";

} else if (
  existeFalse(/^usuario_.*_valido$/) ||
  existeFalse(/^usuario_.*_actualizacion_valido$/)
) {
  resultado = "rechazado";
  motivo = "usuario_relacionado_invalido";

} else if (
  contexto.actualizacion_pendiente_sin_cambios === true
) {
  resultado = "rechazado";
  motivo = "sin_cambios";

} else if (
  contexto.actualizacion_tarea_sin_cambios === true
) {
  resultado = "rechazado";
  motivo = "sin_cambios";

} else if (
  existeFalse(/(^|_)encontrad[oa](_|$)/) &&
  contexto.usuario_encontrado !== false
